SELECT activity_type, description, occurred_at FROM ( SELECT 'ATTENDANCE' AS activity_type, 'QR 체크인' AS description, a.checked_in_at AS occurred_at FROM attendances a WHERE a.member_id = #{memberId}
UNION ALL
SELECT 'WORKOUT' AS activity_type, '운동 기록 저장' AS description, ws.started_at AS occurred_at FROM workout_sessions ws WHERE ws.member_id = #{memberId}
UNION ALL
SELECT 'PAYMENT' AS activity_type, CONCAT( CASE p.payment_method WHEN 'CARD' THEN '카드' WHEN 'CASH' THEN '현금' WHEN 'TRANSFER' THEN '계좌이체' ELSE p.payment_method END, ' 결제 ₩', FORMAT(p.amount, 0) ) AS description, p.paid_at AS occurred_at FROM payments p WHERE p.member_id = #{memberId} AND p.status NOT IN ('PENDING', 'CANCELLED') ) activities ORDER BY occurred_at DESC LIMIT 5

SELECT EXISTS(
    SELECT 1
    FROM user_local_credentials
    WHERE login_id = #{loginId}
)
